import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.cleanup = cleanup;

  const timelines = [];
  const primitiveCleanups = [];

  let meshLoaded = false;
  let hoverTimeline = null;

  // Load the GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;
    scene.traverse((node) => {
      if (node.isMesh) {
        // Ensure materials are PBR-ready; GLB materials are typically StandardMaterial
        // Convert to NodeMaterial if needed for consistency
        if (node.material && !node.material.isNodeMaterial) {
          const oldMat = node.material;
          const newMat = new MeshStandardNodeMaterial({
            color: oldMat.color,
            metalness: oldMat.metalness !== undefined ? oldMat.metalness : 0.6,
            roughness: oldMat.roughness !== undefined ? oldMat.roughness : 0.5,
            map: oldMat.map,
            normalMap: oldMat.normalMap,
            roughnessMap: oldMat.roughnessMap,
            metalnessMap: oldMat.metalnessMap,
            emissive: oldMat.emissive,
            emissiveIntensity: oldMat.emissiveIntensity || 0,
            emissiveMap: oldMat.emissiveMap,
            envMapIntensity: oldMat.envMapIntensity || 1.0,
          });
          node.material = newMat;
        }
      }
    });
    group.add(scene);
    meshLoaded = true;
  });

  // Apply accent rim light (orange-red glow, opposite of key)
  const rimLight = new THREE.PointLight(0xff2a38, 0.7, 6);
  rimLight.position.set(1.5, 0.8, 1.0);
  group.add(rimLight);

  // Apply cinematic primitives
  // 1. Parallax scroll (trigger: scroll)
  const parallaxResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.4,
  });
  if (parallaxResult?.cleanup) primitiveCleanups.push(parallaxResult.cleanup);

  // 2. Magnetic cursor (trigger: hover)
  const magneticResult = ctx.primitives['magnetic-cursor'](group, {
    radius: 1.2,
    strength: 0.35,
  });
  if (magneticResult?.cleanup) primitiveCleanups.push(magneticResult.cleanup);

  // Hover interaction: rise-in entrance (subtle, 0.15 scene units)
  group.userData.handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    timelines.push(hoverTimeline);

    hoverTimeline.to(
      group.position,
      {
        y: group.position.y + 0.15,
        duration: 0.5,
        ease: 'power2.out',
      },
      0
    );
  };

  group.userData.handlers.unhover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    timelines.push(hoverTimeline);

    hoverTimeline.to(
      group.position,
      {
        y: -1.1, // Reset to original position
        duration: 0.5,
        ease: 'power2.out',
      },
      0
    );
  };

  // Click interaction: emit event
  group.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-features' });
  };

  // Entrance animation: weighted settle (subtle rise, overshoot settle)
  const entranceTl = gsap.timeline();
  timelines.push(entranceTl);
  group.position.y -= 0.3; // Start slightly lower
  entranceTl.to(
    group.position,
    {
      y: -1.1,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );
  entranceTl.to(
    group.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
      overshoot: 1.04,
    },
    0.1
  );

  function cleanup() {
    timelines.forEach((tl) => tl.kill());
    primitiveCleanups.forEach((fn) => fn?.());
    rimLight.dispose?.();
    group.traverse((node) => {
      if (node.geometry) node.geometry.dispose();
      if (node.material) {
        if (Array.isArray(node.material)) {
          node.material.forEach((m) => m.dispose?.());
        } else {
          node.material.dispose?.();
        }
      }
    });
  }

  return group;
}
